import{y as t,b as n,c as a,X as r}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const p=JSON.parse('{"title":"Context Management & Semantic Compression Depth (WP-5001)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/CONTEXT_MANAGEMENT_DEPTH.md","filePath":"reference/CONTEXT_MANAGEMENT_DEPTH.md","lastUpdated":1771753292000}'),o={name:"reference/CONTEXT_MANAGEMENT_DEPTH.md"};function i(s,e,d,c,l,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="context-management-semantic-compression-depth-wp-5001" tabindex="-1">Context Management &amp; Semantic Compression Depth (WP-5001) <a class="header-anchor" href="#context-management-semantic-compression-depth-wp-5001" aria-label="Permalink to &quot;Context Management &amp; Semantic Compression Depth (WP-5001)&quot;">​</a></h1><p>This document defines the 4-tier memory architecture and context optimization strategies for long-running <code>thegent</code> sessions.</p><h2 id="_1-4-tier-memory-architecture" tabindex="-1">1. 4-Tier Memory Architecture <a class="header-anchor" href="#_1-4-tier-memory-architecture" aria-label="Permalink to &quot;1. 4-Tier Memory Architecture&quot;">​</a></h2><p>To manage &quot;civilizational-scale&quot; runs without token overflow, <code>thegent</code> implements a tiered memory system:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Name</th><th>Storage</th><th>Persistence</th><th>Usage</th></tr></thead><tbody><tr><td>undefined<strong>L1</strong>undefined</td><td>undefined<strong>Working Memory</strong>undefined</td><td>LLM Context Window</td><td>Ephemeral</td><td>Active prompt, recent tool results, current line of thought.</td></tr><tr><td>undefined<strong>L2</strong>undefined</td><td>undefined<strong>Short-term Memory</strong>undefined</td><td>Redis (Hash)</td><td>Session-long</td><td>Checkpoint snapshots, local variable state, recent <code>RunMeta</code>.</td></tr><tr><td>undefined<strong>L3</strong>undefined</td><td>undefined<strong>Long-term Memory</strong>undefined</td><td>undefined<strong>Supermemory (Graph)</strong>undefined</td><td>Permanent</td><td>Past decisions, research findings, code patterns, MAIF artifacts.</td></tr><tr><td>undefined<strong>L4</strong>undefined</td><td>undefined<strong>Archival Memory</strong>undefined</td><td>undefined<strong>Supermemory (Docs)</strong>undefined</td><td>Perpetual</td><td>Immutable audit trail, historical logs, decommissioned agents.</td></tr></tbody></table><h2 id="_2-semantic-context-compression-wp-5001" tabindex="-1">2. Semantic Context Compression (WP-5001) <a class="header-anchor" href="#_2-semantic-context-compression-wp-5001" aria-label="Permalink to &quot;2. Semantic Context Compression (WP-5001)&quot;">​</a></h2><p>When the L1 context window reaches a threshold (e.g., 85% of capacity), <code>thegent</code> triggers a <strong>Compression Cycle</strong>:</p><h3 id="_2-1-summarization-layers" tabindex="-1">2.1 Summarization Layers <a class="header-anchor" href="#_2-1-summarization-layers" aria-label="Permalink to &quot;2.1 Summarization Layers&quot;">​</a></h3><ul><li>The orchestrator spawns a <strong>Summarizer Agent</strong> to compress the previous 50% of the conversation into a &quot;Semantic Kernel.&quot;</li><li>This kernel captures: <strong>Decisions Made</strong>, <strong>Unresolved Risks</strong>, and <strong>Current Intent</strong>.</li></ul><h3 id="_2-2-semantic-caching" tabindex="-1">2.2 Semantic Caching <a class="header-anchor" href="#_2-2-semantic-caching" aria-label="Permalink to &quot;2.2 Semantic Caching&quot;">​</a></h3><ul><li>Before calling a provider, the orchestrator checks a <strong>Semantic Cache</strong> (Redis + Vector Sim).</li><li>If a semantically similar prompt has been answered (e.g., &quot;how do I verify a MAIF artifact?&quot;), the cached response is used, saving both cost and context space.</li></ul><h2 id="_3-dynamic-context-pruning" tabindex="-1">3. Dynamic Context Pruning <a class="header-anchor" href="#_3-dynamic-context-pruning" aria-label="Permalink to &quot;3. Dynamic Context Pruning&quot;">​</a></h2><p><code>thegent</code> uses a &quot;Priority-Based Pruning&quot; algorithm to clear space:</p><ol><li>undefined<strong>Retain</strong>: Current objective, system instructions, last 3 tool results.</li><li>undefined<strong>Compress</strong>: Previous research summaries, intermediate state transitions.</li><li>undefined<strong>Prune</strong>: Verbose log outputs, duplicate file reads, discarded hypotheses.</li></ol><h2 id="_4-continuity-packets-adr-011" tabindex="-1">4. Continuity Packets (ADR-011) <a class="header-anchor" href="#_4-continuity-packets-adr-011" aria-label="Permalink to &quot;4. Continuity Packets (ADR-011)&quot;">​</a></h2><p>For &quot;handoffs&quot; between agents or across pauses, <code>thegent</code> generates a <strong>Continuity Packet</strong>:</p><ul><li>A highly compressed, structured JSON containing the &quot;Essence of Progress.&quot;</li><li>Enables a new agent to resume a run with 100% semantic fidelity using &lt; 5% of the original token footprint.</li></ul><hr><p><em>Cross-ref: <a href="./ROBUSTNESS_AND_FUTURE_DEPTH.html">ROBUSTNESS_AND_FUTURE_DEPTH.md</a> | <a href="./MAIF_ARTIFACT_SPEC_DEPTH.html">MAIF_ARTIFACT_SPEC_DEPTH.md</a></em></p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p>undefined<strong>Extended on:</strong> 2026-02-17 undefined<strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',31)])])}const f=t(o,[["render",i]]);export{p as __pageData,f as default};
